param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
$replacements=@(@(),@(63),@(65,66),@(0),@(65,0,66),@(0xd800,0xdc00),@(0xfffd))
$actions=@(@('remaining'),@('previous'),@('next'),@('next'),@('remaining'),@('single',65,-1),@('remaining'),@('next'),@('remaining'),@('previous'),@('remaining'),@('next'),@('next'),@('next'),@('next'),@('next'),@('remaining'),@('previous'),@('previous'),@('next'),@('next'),@('remaining'),@('single',0xd800,3),@('single',0xdc00,2147483647),@('remaining'),@('pair',65,0xdc00,3),@('pair',0xd800,65,3),@('pair',0xd800,0xdc00,3),@('reset'),@('remaining'),@('pair',0xd800,0xdc00,-2147483648),@('remaining'),@('next'),@('previous'),@('next'),@('next'),@('next'),@('remaining'),@('pair',65,0xdc00,0),@('pair',0xd800,65,0),@('pair',65,66,0),@('pair',0xdc00,0xd800,0),@('remaining'),@('reset'),@('single',0,0),@('next'),@('remaining'),@('previous'),@('next'),@('reset'),@('remaining'))
$profiles=@()
foreach($profile in 0..7){$fallback=if($profile -eq 7){[Text.EncoderExceptionFallback]::new()}else{[Text.EncoderReplacementFallback]::new([string]::new([char[]][int[]]$replacements[$profile]))};$buffer=$fallback.CreateFallbackBuffer();$steps=@()
 foreach($action in $actions){$before=$buffer.Remaining
  try{switch($action[0]){'remaining'{$result=[ordered]@{ok=$true;value=$buffer.Remaining}}'previous'{$result=[ordered]@{ok=$true;value=$buffer.MovePrevious()}}'next'{$result=[ordered]@{ok=$true;value=[int]$buffer.GetNextChar()}}'reset'{$buffer.Reset();$result=[ordered]@{ok=$true;value=$null}}'single'{$value=$buffer.Fallback([char]$action[1],[int]$action[2]);$result=[ordered]@{ok=$true;value=$value}}'pair'{$value=$buffer.Fallback([char]$action[1],[char]$action[2],[int]$action[3]);$result=[ordered]@{ok=$true;value=$value}}}}
  catch{$e=$_.Exception;while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};$result=[ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$e.ParamName};if($e -is [ArgumentOutOfRangeException]){$result.actualValue=$e.ActualValue};if($e -is [Text.EncoderFallbackException]){$result.index=$e.Index;$result.charUnknown=[int]$e.CharUnknown;$result.charUnknownHigh=[int]$e.CharUnknownHigh;$result.charUnknownLow=[int]$e.CharUnknownLow;$result.isUnknownSurrogate=$e.IsUnknownSurrogate()}}
  $steps+=[ordered]@{action=$action;remainingBefore=$before;result=$result;remainingAfter=$buffer.Remaining}
 }
 $profiles+=[ordered]@{profile=$profile;replacementUnits=$(if($profile -lt 7){,[int[]]$replacements[$profile]}else{$null});nativeBufferType=$buffer.GetType().FullName;factoryDistinct=(-not [object]::ReferenceEquals($buffer,$fallback.CreateFallbackBuffer()));steps=$steps}
}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();profiles=$profiles;qualification='SELECTED_ENCODER_FALLBACK_BUFFER_STATE_ONLY; INTERNAL_RUNTIME_TYPE_MESSAGES_CUSTOMIZATION_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS pinned encoder buffers: eight profiles and $($actions.Count) transitions each"
